{"cmd": "python3 -c "
import json
import os
results_dir = '/opt/public_eval/results'
for f in sorted(os.listdir(results_dir)):
    if f.endswith('.json'):
        with open(os.path.join(results_dir, f)) as fh:
            data = json.load(fh)
        keys = list(data.keys())
        print(f'{f[:20]}... keys: {keys[:10]}')
        if 'aggregate' in data:
            print(f'  aggregate: {data[\"aggregate\"]}')
        if 'score' in data:
            print(f'  score: {data[\"score\"]}')
        if 'cases' in data:
            print(f'  num cases: {len(data[\"cases\"])}')
            first_key = list(data['cases'].keys())[0]
            print(f'  first case: {first_key}, keys: {list(data[\"cases\"][first_key].keys())}')
"
"}
